WITH parsed AS (SELECT id, customer_id, created_at, items, ship_to, attributes, COALESCE(attributes['device'], 'none') AS device_or_default, ship_to.city AS ship_city FROM carts) SELECT ship_city, COUNT(CASE WHEN ship_city = 'Tokyo' THEN 1 END) AS tokyo_count, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, COUNT(CASE WHEN ship_city = 'London' THEN 1 END) AS london_count, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT customer_id) AS distinct_customer_ids, SORT_ARRAY(COLLECT_SET(ship_city)) AS ship_city_list FROM parsed GROUP BY ship_city;
